class DomainError(Exception):
    status_code = 400
    code = 'domain_error'

@app.exception_handler(DomainError)
def handle_domain(request: Request, exc: DomainError):
    return JSONResponse(status_code=exc.status_code,
                        content={'error': {'code': exc.code, 'message': str(exc)}})

def page(query, limit=20, cursor=None):
    if cursor is not None:
        query = query.filter(id__gt=cursor)
    rows = list(query.order_by('id').limit(limit + 1))
    has_more = len(rows) > limit
    rows = rows[:limit]
    return {'items': rows, 'next': rows[-1].id if has_more else None}

