import uuid
from fastapi import BackgroundTasks

JOBS = {}

def run_job(job_id, payload):
    try:
        JOBS[job_id] = {'status': 'done', 'result': len(payload)}
    except Exception as e:
        JOBS[job_id] = {'status': 'failed', 'error': str(e)}

@app.post('/v1/reports', status_code=202)
def create_report(payload: dict, tasks: BackgroundTasks):
    job_id = str(uuid.uuid4())
    JOBS[job_id] = {'status': 'queued'}
    tasks.add_task(run_job, job_id, payload)
    return {'job_id': job_id}

from fastapi import Query

SORTABLE = {'id', 'created_at', 'amount'}

@app.get('/v1/orders')
def list_orders(limit: int = Query(20, ge=1, le=100),
                sort: str = Query('created_at'),
                order: str = Query('desc')):
    if sort not in SORTABLE:
        raise DomainError(f'unsupported sort: {sort}')
    direction = 'DESC' if order.lower() == 'desc' else 'ASC'
    return {'limit': limit, 'sort': sort, 'direction': direction}
